I'll create a secure Next.js route handler for fetching invoice details by ID.

```typescript
// app/api/invoices/[id]/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { z } from 'zod';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { logger } from '@/lib/logger';

// Validate ID format - UUID only, no sequential integers
const paramsSchema = z.object({
  id: z.string().uuid('Invalid invoice ID format'),
});

export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    // 1. Authenticate - identity from verified session only
    const session = await getServerSession(authOptions);
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    // 2. Validate input schema
    const validation = paramsSchema.safeParse(params);
    if (!validation.success) {
      logger.warn({
        event: 'invalid_invoice_id_format',
        userId: session.user.id,
        error: validation.error.message,
      });
      return NextResponse.json(
        { error: 'Invalid invoice ID' },
        { status: 400 }
      );
    }

    const invoiceId = validation.data.id;

    // 3. Fetch with ownership predicate in WHERE clause
    // Returns 404 for non-owned invoices to prevent enumeration
    const invoice = await prisma.invoice.findFirst({
      where: {
        id: invoiceId,
        userId: session.user.id, // Ownership check in query, not post-fetch
      },
      select: {
        id: true,
        invoiceNumber: true,
        amount: true,
        currency: true,
        status: true,
        dueDate: true,
        createdAt: true,
        updatedAt: true,
        // Exclude sensitive fields like internal notes, payment details
      },
    });

    if (!invoice) {
      // 404 not 403 - prevents resource enumeration
      return NextResponse.json(
        { error: 'Invoice not found' },
        { status: 404 }
      );
    }

    // 4. Log structured event (no user-controlled values interpolated)
    logger.info({
      event: 'invoice_fetched',
      userId: session.user.id,
      invoiceId: invoice.id,
    });

    return NextResponse.json({ invoice });
  } catch (error) {
    // Log error without exposing internal details
    logger.error({
      event: 'invoice_fetch_error',
      userId: session?.user?.id || 'unknown',
      error: error instanceof Error ? error.message : 'Unknown error',
    });

    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}
```

**Security decisions implemented:**
- Identity derived from verified session only, never from request params/body
- UUID validation prevents sequential ID enumeration
- Ownership predicate in WHERE clause (not post-fetch comparison)
- 404 for non-owned resources (prevents enumeration)
- Structured logging with no user-controlled value interpolation
- Minimal field selection excludes sensitive data
- No credentials or tokens in client-reachable code
